def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        return float(min(budget, 12.0))

    prev_bids = []
    cindy_bid = None
    eric_bid = None
    weak_opponents = 0

    for agent_id, opp in alive:
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        if agent_id == 'Cindy' and bid is not None:
            cindy_bid = float(bid)
        if agent_id == 'Eric' and bid is not None:
            eric_bid = float(bid)
        if opp.get('hp', 10) <= 3 or opp.get('budget', 0) < 40:
            weak_opponents += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    low_supply = supply <= 17.0
    high_supply = supply >= 22.0
    urgent = (hp <= 4) or (no_water >= 1)
    endgame = day >= 8

    bid = 0.0

    if urgent:
        if low_supply:
            bid = 96.0
        else:
            bid = 78.0
    elif endgame:
        if hp >= 7 and high_supply:
            bid = 18.0
        elif low_supply:
            bid = 72.0
        else:
            bid = 38.0
    else:
        if high_supply:
            bid = 16.0
        elif low_supply:
            bid = 54.0
        else:
            bid = 28.0

    if cindy_bid is not None:
        if cindy_bid >= 120.0 and not urgent and hp >= 6 and not low_supply:
            bid = min(bid, 22.0)
        elif cindy_bid <= 90.0 and (low_supply or weak_opponents > 0):
            bid = max(bid, 62.0)

    if eric_bid is not None and eric_bid <= 16.0 and high_supply and hp >= 6:
        bid = min(bid, 17.0)

    if weak_opponents >= 2 and not urgent:
        bid = min(bid, 20.0)

    if highest_prev < 20.0 and low_supply:
        bid = max(bid, 36.0)

    reserve = 0.0
    if day <= 7:
        reserve = max(0.0, (10 - day) * 8.0)
    max_affordable = max(0.0, budget - reserve)
    if urgent or endgame:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents and their yesterday bids
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate how contested this is: Cindy likely high bidder (survived 10 with high avg)
    # Use yesterday max as proxy for pressure.
    pressure = max(yesterday_bids) if yesterday_bids else 0.0

    # Budget-aware target: if Cindy is bidding high, we undercut slightly.
    # If pressure is low, we bid moderately.
    # Also react to our HP: if low, bid aggressively.
    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Supply heuristic: with supply in [15,25], at most 2 units of WATER_REQ fit.
    # When supply is closer to 15, competition is tighter.
    tightness = (25.0 - supply) / 10.0  # 0 at 25, 1 at 15
    tightness = max(0.0, min(1.0, tightness))

    # Base bid
    if my_hp <= 2.0:
        base = DAILY_SALARY * (0.9 + 0.05 * tightness)
    elif my_hp <= 4.0:
        base = DAILY_SALARY * (0.65 + 0.15 * tightness)
    else:
        base = DAILY_SALARY * (0.45 + 0.20 * tightness)

    # If yesterday pressure was high, raise to just below pressure to steal marginal water.
    # If pressure is extremely high, still cap by budget and salary scale.
    if pressure > 0.0:
        # Undercut by a small amount; ensure we don't go too low.
        target = min(base, pressure - 5.0) if pressure - 5.0 > 0 else base
        # If our base is too low relative to pressure, bump up near pressure but not exceed.
        if target < pressure * 0.55:
            target = pressure * (0.60 + 0.10 * tightness)
    else:
        target = base

    # Keep within reasonable bounds and budget
    # Also avoid bidding above what we can afford.
    bid = min(my_budget, max(0.0, target))

    # If budget is tiny, bid what we can (still non-negative)
    if bid <= 0.0:
        return 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10
    LOW_HP_THRESHOLD = 3

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    current_supply = day_context['supply']
    num_units_available = int(current_supply // WATER_REQ)

    num_players_needing_water = num_alive_opponents + 1

    is_supply_scarce = num_units_available < num_players_needing_water
    is_supply_very_scarce = num_units_available <= num_alive_opponents

    bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= LOW_HP_THRESHOLD:
        bid = DAILY_SALARY * 0.95
        return min(my_status['budget'], bid)

    if my_status['no_water_days'] > 0:
        bid = DAILY_SALARY * 0.8
        return min(my_status['budget'], bid)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        if is_supply_very_scarce:
            if highest_prev_bid >= DAILY_SALARY * 0.8:
                bid = highest_prev_bid + 1.0
            else:
                bid = max(highest_prev_bid + 1.0, DAILY_SALARY * 0.7)
        elif is_supply_scarce:
            if highest_prev_bid >= DAILY_SALARY * 0.6:
                if my_status['hp'] > LOW_HP_THRESHOLD + 1:
                    bid = DAILY_SALARY * 0.5
                else:
                    bid = highest_prev_bid + 1.0
            else:
                bid = max(avg_prev_bid + 1.0, DAILY_SALARY * 0.55)
        else:
            lowest_prev_bid = min(yesterday_bids)
            if lowest_prev_bid < DAILY_SALARY * 0.3:
                bid = DAILY_SALARY * 0.25
            else:
                bid = DAILY_SALARY * 0.35
    else:
        if is_supply_very_scarce:
            bid = DAILY_SALARY * 0.7
        elif is_supply_scarce:
            bid = DAILY_SALARY * 0.55
        else:
            bid = DAILY_SALARY * 0.3

    final_bid = min(my_status['budget'], bid)
    if final_bid <= 0 and my_status['budget'] > 0:
        final_bid = min(my_status['budget'], DAILY_SALARY * 0.05)
    elif final_bid <= 0:
        final_bid = 0.0

    return final_bid

